import * as React from 'react';

import Calendar from '~components/calendar';
import Dropdown from '~components/dropdown/internal';

import i18nStrings from './i18n-strings';

export default function CalendarPage() {
  return (
    <article>
      <h1>Calendar page for a11y tests</h1>
      <Dropdown
        minWidth="trigger"
        maxWidth="trigger"
        stretchHeight={true}
        open={true}
        onOutsideClick={() => {}}
        onMouseDown={() => {}}
        trigger={null}
        content={
          <>
            <Calendar
              value="2021-8-20"
              onChange={() => {}}
              locale="en-GB"
              ariaLabel="Certificate expiration date, calendar"
              startOfWeek={1}
              isDateEnabled={date => date.getDay() !== 6 && date.getDay() !== 0}
              dateDisabledReason={date => {
                if (date.getDay() === 6) {
                  return 'Saturday';
                }

                if (date.getDay() === 0) {
                  return 'Sunday';
                }

                return '';
              }}
              i18nStrings={i18nStrings}
            />
            <Calendar
              value=""
              onChange={() => {}}
              locale="en-GB"
              ariaLabel="Scheduled launch date, calendar"
              startOfWeek={1}
              isDateEnabled={date => date.getDay() !== 6 && date.getDay() !== 0}
              i18nStrings={i18nStrings}
            />
          </>
        }
      />
    </article>
  );
}
